//! 🐎️ Real synchronous canonical guest imports suspend until the original borrowed caller replies.
use super::{wasmtime as bridge,slot::OperationSlot,EntityIdentityAuthority,OriginalOperationReceiver};
use semio_framework_value::{ValueError,ValueRefusalKind};
use wasmtime::{Config,Engine,Store,component::{Component,Linker}};
struct State{slot:OperationSlot}
impl bridge::OperationHostStore for State{fn operation_slot(&mut self)->&mut OperationSlot{&mut self.slot}fn operation_log(&mut self,_:String,_:String){}fn operation_now_ms(&mut self)->i64{0}fn operation_trace_span(&mut self,_:String){}}
#[test]
fn real_sync_guest_imports_preserve_original_admission_and_refuse_before_physical_work(){
 semio_framework_async::block_on(async{
  let fixture:serde_json::Value=serde_json::from_str(include_str!("../../📨️slot/🧫️fixtures/🔣️.json")).unwrap();let law=&fixture["authority"];let ceiling=law["ceiling"].as_u64().unwrap()as usize;let prior=law["prior"].as_u64().unwrap()as usize;let bytes=law["guest"].as_u64().unwrap();
  let mut config=Config::new();config.wasm_component_model(true).wasm_component_model_async(true);let engine=Engine::new(&config).unwrap();let component=Component::new(&engine,include_str!("../../🧫️fixtures/🐎️wasmtime/🕸️.wat")).unwrap();let mut linker=Linker::new(&engine);bridge::register(&mut linker).unwrap();
  for refused in [false,true]{
   let mut store=Store::new(&engine,State{slot:OperationSlot::new()});let instance=linker.instantiate_async(&mut store,&component).await.unwrap();let begin=instance.get_typed_func::<(),(Result<u64,u32>,)>(&mut store,"begin").unwrap();let run=instance.get_typed_func::<(u64,u64),(u32,)>(&mut store,"run").unwrap();let physical=instance.get_typed_func::<(),(u32,)>(&mut store,"physical").unwrap();
   let original_calls=std::sync::atomic::AtomicUsize::new(0);let mut observe=|_|{original_calls.fetch_add(1,std::sync::atomic::Ordering::Relaxed);true};let mut original_port=|_:semio_framework_value::native_encoding::NativeEncodeAllocation|if refused{Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,"original port refused physical guest storage"))}else{Ok(())};let mut identity=EntityIdentityAuthority::new_forwarded(ceiling,&mut observe,&mut original_port).unwrap();if !refused{identity.encode::<_,ValueError>(|control|control.charge(prior)).unwrap();}
   let mut receiver=OriginalOperationReceiver::new(&mut identity);let mut guest_maximum=0;
   let output=store.run_concurrent(async|accessor|bridge::receive(accessor,&mut receiver,async{let(grant,)=begin.call_concurrent(accessor,()).await?;guest_maximum=grant.unwrap();let(code,)=run.call_concurrent(accessor,(bytes,guest_maximum)).await?;Ok::<_,wasmtime::Error>(code)}).await).await.unwrap().unwrap();
   assert_eq!(output,if refused{2}else{0});let(actual,)=store.run_concurrent(async|accessor|physical.call_concurrent(accessor,()).await).await.unwrap().unwrap();assert_eq!(actual,if refused{0}else{1});drop(receiver);let receipt=identity.pause_forwarded().unwrap();assert_eq!(receipt.owned_bytes(),if refused{0}else{law["expected"].as_u64().unwrap()as usize});assert!(original_calls.load(std::sync::atomic::Ordering::Relaxed)>0);
   println!("[DEBUG] Actual Wasmtime original borrow: refused={refused} synchronousGuestPhysicalEffects={actual} originalCumulativeOwned={} noAuthorityInStaticStore=true",receipt.owned_bytes());
  }
 });
}

#[test]
fn actual_generated_return_dtos_report_borrowed_storage_without_copying_payloads(){
 use super::{return_types::{reactor,codec,types,pure},return_walk};
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🐎️wasmtime/returns.json")).unwrap();let bytes=|value:&serde_json::Value|serde_json::from_value::<Vec<u8>>(value.clone()).unwrap();
 let pair=codec::DocumentPair{pack:bytes(&fixture["pair"]["pack"]),spr:bytes(&fixture["pair"]["spr"])};let original=pair.pack.as_ptr();let mut sizes=Vec::new();return_walk::walk_document_pair(&pair,&mut|kind,count|{assert_eq!(kind,pure::OperationReturnAllocation::Bytes);sizes.push(count);Ok(())}).unwrap();assert_eq!(sizes,serde_json::from_value::<Vec<usize>>(fixture["pair"]["expectedBytes"].clone()).unwrap());assert_eq!(pair.pack.as_ptr(),original);
 let sqlite=codec::SnapshotFileResult::Done(codec::SnapshotFile{bytes:bytes(&fixture["sqlite"]["bytes"]),diagnostics:bytes(&fixture["sqlite"]["diagnostics"])});sizes.clear();return_walk::walk_snapshot_file_result(&sqlite,&mut|kind,count|{assert_eq!(kind,pure::OperationReturnAllocation::Bytes);sizes.push(count);Ok(())}).unwrap();assert_eq!(sizes,serde_json::from_value::<Vec<usize>>(fixture["sqlite"]["expectedBytes"].clone()).unwrap());
 let retained=&fixture["turn"]["retainedReceipt"];let input=&retained["input"];let spent=&retained["spent"];let number=|value:&serde_json::Value,key:&str|value[key].as_u64().unwrap();let grant=|value:&serde_json::Value|reactor::RetainedGrant{maximum_items:number(value,"maximumItems"),maximum_copy_bytes:number(value,"maximumCopyBytes"),maximum_capacity_bytes:number(value,"maximumCapacityBytes"),maximum_release_bytes:number(value,"maximumReleaseBytes"),maximum_depth:number(value,"maximumDepth")};
 let retained_receipt=reactor::RetainedTurnReceipt{input:reactor::RetainedTurnInput{operation:number(input,"operation"),generation:number(input,"generation"),epoch:number(input,"epoch"),grant:grant(&input["grant"])},spent:reactor::RetainedProgress{copied_items:number(spent,"copiedItems"),copied_bytes:number(spent,"copiedBytes"),retained_capacity_bytes:number(spent,"retainedCapacityBytes"),released_bytes:number(spent,"releasedBytes")},remaining:grant(&retained["remaining"])};
 let project_grant=|value:&reactor::RetainedGrant|serde_json::json!({"maximumItems":value.maximum_items,"maximumCopyBytes":value.maximum_copy_bytes,"maximumCapacityBytes":value.maximum_capacity_bytes,"maximumReleaseBytes":value.maximum_release_bytes,"maximumDepth":value.maximum_depth});let projected=serde_json::json!({"input":{"operation":retained_receipt.input.operation,"generation":retained_receipt.input.generation,"epoch":retained_receipt.input.epoch,"grant":project_grant(&retained_receipt.input.grant)},"spent":{"copiedItems":retained_receipt.spent.copied_items,"copiedBytes":retained_receipt.spent.copied_bytes,"retainedCapacityBytes":retained_receipt.spent.retained_capacity_bytes,"releasedBytes":retained_receipt.spent.released_bytes},"remaining":project_grant(&retained_receipt.remaining)});assert_eq!(projected,*retained);assert_eq!(retained_receipt.input.grant.maximum_copy_bytes,0);assert_eq!(retained_receipt.remaining.maximum_copy_bytes,0);
 let turn=reactor::TurnResult{retained_receipt,ui_patches:Vec::new(),effects:Vec::new(),presence:vec![reactor::PresenceUpdate{update:bytes(&fixture["turn"]["presence"])}],next_wake:None,status:reactor::TurnStatus::Faulted(bytes(&fixture["turn"]["status"])),fuel_used:0,command_ingress:reactor::CommandIngressStatus{kind:0,cursor:reactor::CommandPageCursor{owner:0,generation:0,command_index:0,command_count:0,instance:0,seq:0,kind:0,page_index:0,page_count:0,item_count:0,metadata:0},fault:bytes(&fixture["turn"]["ingress"])},cold_pair_ingress:reactor::ColdPairIngressStatus::Idle,lifecycle_receipt:None,ui_patch_receipt:None};let presence=turn.presence.as_ptr();let mut arrays=Vec::new();sizes.clear();return_walk::walk_turn(&turn,&mut|kind,count|{if kind==pure::OperationReturnAllocation::Bytes{sizes.push(count)}else{arrays.push((kind,count))}Ok(())}).unwrap();assert_eq!(sizes,serde_json::from_value::<Vec<usize>>(fixture["turn"]["expectedBytes"].clone()).unwrap());assert!(arrays.contains(&(pure::OperationReturnAllocation::PresenceUpdateList,1)));assert_eq!(turn.presence.as_ptr(),presence);
 let mut calls=0;let refused=return_walk::walk_document_pair(&pair,&mut|_,_|{calls+=1;Err(ValueError::literal(ValueRefusalKind::Canceled,"original return admission canceled"))}).unwrap_err();assert_eq!(refused.kind,ValueRefusalKind::Canceled);assert_eq!(calls,1);
 let pending=&fixture["sqlitePending"];let demand=&pending["demands"];let pending=codec::SnapshotRetirement{ticket:pending["ticket"].as_u64().unwrap(),owned_bytes:pending["ownedBytes"].as_u64().unwrap(),refusal:u32::try_from(pending["refusal"].as_u64().unwrap()).unwrap(),native_pending:pending["nativePending"].as_bool().unwrap(),output_pending:pending["outputPending"].as_bool().unwrap(),terminal:pending["terminal"].as_bool().unwrap(),demands:codec::SnapshotDemands{items:demand["items"].as_u64().unwrap(),copy_bytes:demand["copyBytes"].as_u64().unwrap(),capacity_bytes:demand["capacityBytes"].as_u64().unwrap(),release_bytes:demand["releaseBytes"].as_u64().unwrap(),depth:demand["depth"].as_u64().unwrap()}};assert_eq!(pending.refusal,0);let scalar=serde_json::json!({"refusal":pending.refusal,"ticket":pending.ticket,"ownedBytes":pending.owned_bytes,"nativePending":pending.native_pending,"outputPending":pending.output_pending,"terminal":pending.terminal,"demands":{"items":pending.demands.items,"copyBytes":pending.demands.copy_bytes,"capacityBytes":pending.demands.capacity_bytes,"releaseBytes":pending.demands.release_bytes,"depth":pending.demands.depth}});assert_eq!(scalar,fixture["sqlitePending"]);return_walk::walk_snapshot_file_result(&codec::SnapshotFileResult::Pending(pending),&mut|_,_|panic!("inline original retirement result requested native storage")).unwrap();
 let error=types::PluginError::Fault(vec![1]);sizes.clear();return_walk::walk_error(&error,&mut|_,count|{sizes.push(count);Ok(())}).unwrap();assert_eq!(sizes,[1]);let refused=types::PluginError::OperationRefusal(1);return_walk::walk_error(&refused,&mut|_,_|panic!("scalar original refusal allocated return storage")).unwrap();println!("[DEBUG] Actual Wasmtime-generated return DTOs: pair=true sqlite=true turn=true refusalStopsBeforeNextField=true originalPointers=true independentSerde=true");
}

#[test]
fn typed_return_reservation_is_closed_and_part_of_original_scalar_transport(){
 use super::slot::{OperationRequest,OperationReturnAllocation,OperationReply};
 let request=OperationRequest::ReserveReturn{kind:OperationReturnAllocation::Bytes,count:11};let mut slot=OperationSlot::new();let waker=std::task::Waker::noop();let mut context=std::task::Context::from_waker(waker);let mut posted=None;assert_eq!(slot.poll_request(request,&mut posted,&mut context),std::task::Poll::Ready(OperationReply::Code(6)));slot.arm().unwrap();assert_eq!(slot.poll_request(request,&mut posted,&mut context),std::task::Poll::Pending);assert_eq!(slot.take_request(),Some(request));slot.reply(OperationReply::Code(2)).unwrap();assert_eq!(slot.poll_request(request,&mut posted,&mut context),std::task::Poll::Ready(OperationReply::Code(2)));println!("[DEBUG] Typed original return reservation: closedBytesClass=true count11Unmodified=true unboundRefused=true originalRefusalPreserved=true");
}

#[test]
fn canonical_native_return_lifting_waits_for_original_preallocation_admission(){
 semio_framework_async::block_on(async{
  let fixture:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🐎️wasmtime/returns.json")).unwrap();let law=&fixture["reservation"];let ceiling=law["ceiling"].as_u64().unwrap()as usize;let prior=law["prior"].as_u64().unwrap()as usize;let guest=law["guest"].as_u64().unwrap();let count=law["return"].as_u64().unwrap();let mut config=Config::new();config.wasm_component_model(true).wasm_component_model_async(true);let engine=Engine::new(&config).unwrap();let component=Component::new(&engine,include_str!("../../🧫️fixtures/🐎️wasmtime/🕸️.wat")).unwrap();let mut linker=Linker::new(&engine);bridge::register(&mut linker).unwrap();
  for refused in [false,true]{let mut store=Store::new(&engine,State{slot:OperationSlot::new()});let instance=linker.instantiate_async(&mut store,&component).await.unwrap();let begin=instance.get_typed_func::<(),(Result<u64,u32>,)>(&mut store,"begin").unwrap();let run=instance.get_typed_func::<(u64,u64,u64),(Result<Vec<u8>,u32>,)>(&mut store,"return-bytes").unwrap();let physical=instance.get_typed_func::<(),(u32,)>(&mut store,"physical").unwrap();let calls=std::sync::atomic::AtomicUsize::new(0);let mut observe=|_|{calls.fetch_add(1,std::sync::atomic::Ordering::Relaxed);true};let mut port=|allocation:semio_framework_value::native_encoding::NativeEncodeAllocation|if refused&&allocation.bytes==count as usize{Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,"original caller refused return lifting"))}else{Ok(())};let mut identity=EntityIdentityAuthority::new_forwarded(ceiling,&mut observe,&mut port).unwrap();identity.encode::<_,ValueError>(|control|control.charge(prior)).unwrap();let mut receiver=OriginalOperationReceiver::new(&mut identity);let output=store.run_concurrent(async|accessor|bridge::receive(accessor,&mut receiver,async{let(maximum,)=begin.call_concurrent(accessor,()).await?;let(output,)=run.call_concurrent(accessor,(guest,maximum.unwrap(),count)).await?;Ok::<_,wasmtime::Error>(output)}).await).await.unwrap().unwrap();let bytes=output.as_ref().map_or(0,Vec::len);receiver.verify_reserved_return(bytes).unwrap();if refused{assert_eq!(output,Err(2))}else{assert_eq!(output.unwrap(),(0..count as u8).collect::<Vec<_>>())}let(actual,)=store.run_concurrent(async|accessor|physical.call_concurrent(accessor,()).await).await.unwrap().unwrap();assert_eq!(actual,if refused{0}else{1});drop(receiver);let receipt=identity.pause_forwarded().unwrap();assert_eq!(receipt.owned_bytes(),if refused{prior+guest as usize}else{law["expected"].as_u64().unwrap()as usize});assert!(calls.load(std::sync::atomic::Ordering::Relaxed)>0);println!("[DEBUG] Actual canonical native return: refused={refused} liftedBytes={bytes} physicalGuestPublish={actual} originalCumulativeOwned={} reservationBeforeLift=true independentSerde=true",receipt.owned_bytes());}
 });
}

#[test]
fn actual_receiving_protocol_refusals_remain_typed_borrowed_values() {
 semio_framework_async::block_on(async {
  let fixture:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🐎️wasmtime/returns.json")).unwrap();
  let mut config=Config::new();config.wasm_component_model(true).wasm_component_model_async(true);let engine=Engine::new(&config).unwrap();let component=Component::new(&engine,include_str!("../../🧫️fixtures/🐎️wasmtime/🕸️.wat")).unwrap();let mut linker=Linker::new(&engine);bridge::register(&mut linker).unwrap();
  for row in fixture["receivingRefusals"].as_array().unwrap() {
   let occupied=row["stage"].as_str().unwrap()=="occupied";
   let mut store=Store::new(&engine,State{slot:OperationSlot::new()});let instance=linker.instantiate_async(&mut store,&component).await.unwrap();let begin=instance.get_typed_func::<(),(Result<u64,u32>,)>(&mut store,"begin").unwrap();if occupied{store.data_mut().slot.arm().unwrap();}
   let mut observe=|_|true;let mut port=|_:semio_framework_value::native_encoding::NativeEncodeAllocation|Ok(());let mut identity=EntityIdentityAuthority::new_forwarded(fixture["reservation"]["ceiling"].as_u64().unwrap()as usize,&mut observe,&mut port).unwrap();let mut receiver=OriginalOperationReceiver::new(&mut identity);
   let result=store.run_concurrent(async|accessor|bridge::receive(accessor,&mut receiver,async{let(value,)=begin.call_concurrent(accessor,()).await?;assert!(value.is_ok());Ok::<_,wasmtime::Error>(())}).await).await.unwrap();
   let bridge::ReceiveError::Refused(error)=result.unwrap_err() else { panic!("receiving refusal changed its domain") };
   let storage=if matches!(&error.message,std::borrow::Cow::Borrowed(_)){"borrowed"}else{"owned"};let oracle=serde_json::json!({"stage":row["stage"],"code":crate::operation_authority::refusal_code(error.kind),"messageStorage":storage});assert_eq!(&oracle,row);assert_eq!(error.kind,ValueRefusalKind::InvariantViolated);
   if occupied{store.data_mut().slot.disarm(1);}else{store.data_mut().slot.arm().unwrap();store.data_mut().slot.disarm(1);}
   drop(receiver);assert_eq!(identity.pause_forwarded().unwrap().owned_bytes(),0);
   println!("[DEBUG] Actual receiving refusal stage={} typedOriginal=true borrowedMessage={} scalarOutput=true independentSerde=true",row["stage"],storage=="borrowed");
  }
 });
}
